import {
  Object3D,
  Mesh,
  PlaneGeometry,
  Texture,
  Vector3,
  Euler
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  // ------- Geometry -------
  const geometry = new PlaneGeometry(1, 1, 1, 1);

  // ------- Texture -------
  let texture = null;
  const imageUrl = config.assets?.imageUrl;
  if (imageUrl) {
    texture = ctx.textureLoader(imageUrl);
  }

  // ------- Material -------
  const material = new MeshBasicNodeMaterial();
  if (texture) {
    material.map = texture;
    // Ensure correct mapping orientation
    material.map.flipY = false;
  }

  // ------- Mesh -------
  const mesh = new Mesh(geometry, material);
  mesh.name = config.id ?? 'node';

  // ------- Transform -------
  const pos = config.position ?? [-3.2, -0.3, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // ------- Cinematic Primitives -------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') {
        fn(mesh, primitive.params);
      }
    }
  }

  // ------- Event Handlers Placeholder -------
  mesh.userData.handlers = {};

  // ------- Cleanup ----------
  const timelines = [];

  mesh.userData.cleanup = () => {
    // Kill GSAP timelines
    timelines.forEach(t => t.kill());

    // Dispose resources
    geometry.dispose();
    material.dispose();
    if (texture) {
      texture.dispose();
    }

    // Remove from parent if attached
    if (mesh.parent) {
      mesh.parent.remove(mesh);
    }
  };

  return mesh;
}
